<?php
namespace App\Services\Hr\Meals;
use Carbon\CarbonImmutable;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class MealProgrammeService{
 public function generate(string$programId,string$date,string$actor,bool$commit=false,bool$lateOverride=false,?string$reason=null):array{$program=DB::table('hr_meal_program_versions')->where('id',$programId)->where('status','approved')->first();abort_unless($program,404);$day=CarbonImmutable::parse($date,$program->timezone)->startOfDay();abort_unless($day->betweenIncluded(CarbonImmutable::parse($program->effective_from,$program->timezone),CarbonImmutable::parse($program->effective_until??'9999-12-31',$program->timezone)),422,'Meal programme is not effective on this date.');$serviceDays=json_decode($program->service_days,true)?:[];$exclusions=json_decode($program->service_exclusions,true)?:[];abort_unless(in_array($day->dayOfWeekIso,$serviceDays,true)&&!in_array($day->toDateString(),$exclusions,true),422,'The selected date is not a programme service day.');$cutoff=CarbonImmutable::parse($day->toDateString().' '.$program->order_cutoff_local,$program->timezone);if(now($program->timezone)->greaterThan($cutoff)){abort_unless($lateOverride&&$reason,409,'Order cutoff has passed; an authorized reasoned override is required.');}$rules=json_decode($program->eligibility_rules,true)?:[];$subsidy=json_decode($program->subsidy_rules,true)?:[];$finance=json_decode($program->finance_treatment,true)?:[];$menu=DB::table('hr_meal_menus')->where('program_version_id',$program->id)->where('status','active')->whereDate('available_from','<=',$date)->whereDate('available_until','>=',$date)->first();abort_unless($menu,422,'No active menu covers the service date.');$vendor=DB::table('hr_meal_vendors')->where('id',$menu->vendor_id)->first();abort_unless($vendor,422);$items=DB::table('hr_meal_menu_items')->where('menu_id',$menu->id)->where('status','active')->get()->keyBy('id');$staff=DB::table('staff as s')->join('hr_employment_assignments as a','a.staff_id','=','s.id')->whereNull('s.deleted_at')->where('s.company_id',$program->company_id)->where('a.company_id',$program->company_id)->where('a.location_code',$program->location_code)->whereDate('a.effective_from','<=',$date)->where(fn($q)=>$q->whereNull('a.effective_until')->orWhereDate('a.effective_until','>=',$date))->select(['s.id','s.staff_type','s.code','a.id as assignment_id','a.location_code','a.default_shift_code'])->get();$rows=[];$skipped=[];foreach($staff as$employee){if(!empty($rules['staff_types'])&&!in_array($employee->staff_type,$rules['staff_types'],true)){$skipped[]=['staff_id'=>$employee->id,'reason'=>'staff_type_ineligible'];continue;}$profile=DB::table('hr_meal_dietary_profiles')->where('staff_id',$employee->id)->where('opted_in',true)->whereDate('effective_from','<=',$date)->where(fn($q)=>$q->whereNull('effective_until')->orWhereDate('effective_until','>=',$date))->first();$preference=DB::table('hr_meal_preferences')->where('staff_id',$employee->id)->where('program_version_id',$program->id)->where('opted_in',true)->whereDate('effective_from','<=',$date)->where(fn($q)=>$q->whereNull('effective_until')->orWhereDate('effective_until','>=',$date))->latest('effective_from')->first();if(!$profile||!$preference){$skipped[]=['staff_id'=>$employee->id,'reason'=>'not_opted_in_or_no_preference'];continue;}$override=DB::table('hr_meal_order_overrides')->where('staff_id',$employee->id)->where('program_version_id',$program->id)->whereDate('service_date',$date)->first();if($override?->action==='skip'){$skipped[]=['staff_id'=>$employee->id,'reason'=>'employee_skip'];continue;}if(($rules['exclude_approved_leave']??true)&&DB::table('hr_leave_requests')->where('staff_id',$employee->id)->where('status','approved')->whereDate('start_date','<=',$date)->whereDate('end_date','>=',$date)->exists()){$skipped[]=['staff_id'=>$employee->id,'reason'=>'approved_leave'];continue;}$itemId=$override?->menu_item_id?:$preference->default_menu_item_id;$item=$items->get($itemId);if(!$item){$skipped[]=['staff_id'=>$employee->id,'reason'=>'menu_item_unavailable'];continue;}$gross=(float)$item->unit_price+(float)$item->tax_amount;$percent=max(0,min(100,(float)($subsidy['employer_percent']??0)));$employer=$gross*$percent/100;if(isset($subsidy['employer_cap']))$employer=min($employer,(float)$subsidy['employer_cap']);$scale=(int)($subsidy['rounding_scale']??2);$employer=round($employer,$scale);$employeeShare=round($gross-$employer,$scale);$rows[]=['id'=>(string)Str::uuid(),'company_id'=>$program->company_id,'program_version_id'=>$program->id,'staff_id'=>$employee->id,'menu_item_id'=>$item->id,'service_date'=>$date,'location_code'=>$program->location_code,'fulfilment_label'=>$profile->fulfilment_label,'eligibility_snapshot'=>json_encode(['staff_type'=>$employee->staff_type,'assignment_id'=>$employee->assignment_id,'location_code'=>$employee->location_code,'shift_code'=>$employee->default_shift_code,'rules'=>$rules,'override_id'=>$override?->id],JSON_THROW_ON_ERROR),'menu_item_snapshot'=>json_encode(['code'=>$item->code,'name'=>$item->name,'fulfilment_category'=>$item->fulfilment_category,'unit_price'=>$item->unit_price,'tax_amount'=>$item->tax_amount,'delivery_fee_share'=>0],JSON_THROW_ON_ERROR),'gross_amount'=>$gross,'employer_subsidy_amount'=>$employer,'employee_share_amount'=>$employeeShare,'currency'=>$vendor->currency,'employee_recovery_mode'=>$program->employee_recovery_mode,'status'=>'generated','generation_key'=>'meal|'.$program->id.'|'.$employee->id.'|'.$date,'generated_by'=>$actor,'generated_at'=>now(),'created_at'=>now(),'updated_at'=>now()];}if($rows&&(float)$vendor->delivery_fee>0){$scale=(int)($subsidy['rounding_scale']??2);$allocated=0;foreach($rows as$i=>&$row){$share=$i===array_key_last($rows)?round((float)$vendor->delivery_fee-$allocated,$scale):round((float)$vendor->delivery_fee/count($rows),$scale);$allocated+=$share;$row['gross_amount']=(float)$row['gross_amount']+$share;if(($finance['delivery_fee_payer']??'employer')==='employee')$row['employee_share_amount']=(float)$row['employee_share_amount']+$share;else$row['employer_subsidy_amount']=(float)$row['employer_subsidy_amount']+$share;$snapshot=json_decode($row['menu_item_snapshot'],true);$snapshot['delivery_fee_share']=$share;$row['menu_item_snapshot']=json_encode($snapshot,JSON_THROW_ON_ERROR);}unset($row);}$preview=['program_id'=>$program->id,'service_date'=>$date,'eligible_count'=>count($rows),'skipped_count'=>count($skipped),'employee_orders'=>$rows,'skipped'=>$skipped,'late_override'=>$lateOverride,'late_override_reason'=>$reason];if(!$commit)return$preview;return DB::transaction(function()use($rows,$preview,$program,$actor){foreach($rows as$row)DB::table('hr_meal_employee_orders')->insertOrIgnore($row);$this->event('meal_program',$program->id,'orders_generated',null,null,['service_date'=>$preview['service_date'],'eligible_count'=>$preview['eligible_count'],'skipped_count'=>$preview['skipped_count'],'late_override'=>$preview['late_override'],'late_override_reason'=>$preview['late_override_reason']],$actor);return$preview+['committed'=>true];});}
 public function consolidate(string$programId,string$date,string$deliveryDue,string$actor):object{return DB::transaction(function()use($programId,$date,$deliveryDue,$actor){$program=DB::table('hr_meal_program_versions')->where('id',$programId)->where('status','approved')->first();abort_unless($program,404);$menu=DB::table('hr_meal_menus')->where('program_version_id',$programId)->where('status','active')->whereDate('available_from','<=',$date)->whereDate('available_until','>=',$date)->first();abort_unless($menu,422);abort_if(DB::table('hr_meal_vendor_orders')->where('program_version_id',$programId)->where('vendor_id',$menu->vendor_id)->whereDate('service_date',$date)->exists(),409,'Vendor order already exists.');$orders=DB::table('hr_meal_employee_orders')->where('program_version_id',$programId)->whereDate('service_date',$date)->where('status','generated')->lockForUpdate()->get();abort_if($orders->isEmpty(),422,'No generated employee orders exist.');$vendor=DB::table('hr_meal_vendors')->where('id',$menu->vendor_id)->first();$groups=$orders->groupBy('menu_item_id');abort_if($vendor->daily_capacity&&$orders->count()>$vendor->daily_capacity,422,'Vendor daily capacity would be exceeded.');if($menu->capacity)abort_if($orders->count()>$menu->capacity,422,'Menu capacity would be exceeded.');$lines=[];$subtotal=0;$tax=0;foreach($groups as$itemId=>$group){$snapshot=json_decode($group->first()->menu_item_snapshot,true);$qty=$group->count();$lineSubtotal=$qty*(float)$snapshot['unit_price'];$lineTax=$qty*(float)$snapshot['tax_amount'];$lines[]=['id'=>(string)Str::uuid(),'menu_item_id'=>$itemId,'ordered_quantity'=>$qty,'unit_price'=>$snapshot['unit_price'],'tax_amount'=>$lineTax,'line_total'=>$lineSubtotal+$lineTax,'created_at'=>now(),'updated_at'=>now()];$subtotal+=$lineSubtotal;$tax+=$lineTax;}$employer=(float)$orders->sum('employer_subsidy_amount');$employee=(float)$orders->sum('employee_share_amount');$total=$subtotal+$tax+(float)$vendor->delivery_fee;abort_if($vendor->minimum_order_amount!==null&&$total<(float)$vendor->minimum_order_amount,422,'Vendor minimum order amount is not met.');$payload=['program_id'=>$programId,'vendor_id'=>$vendor->id,'menu_id'=>$menu->id,'service_date'=>$date,'lines'=>array_map(fn($l)=>array_intersect_key($l,array_flip(['menu_item_id','ordered_quantity','unit_price','tax_amount','line_total'])),$lines),'subtotal'=>$subtotal,'tax'=>$tax,'delivery_fee'=>$vendor->delivery_fee,'total'=>$total,'employer'=>$employer,'employee'=>$employee,'currency'=>$vendor->currency];$id=(string)Str::uuid();DB::table('hr_meal_vendor_orders')->insert(['id'=>$id,'company_id'=>$program->company_id,'program_version_id'=>$programId,'vendor_id'=>$vendor->id,'menu_id'=>$menu->id,'service_date'=>$date,'location_code'=>$program->location_code,'delivery_due_at'=>$deliveryDue,'status'=>'draft','subtotal'=>$subtotal,'tax_amount'=>$tax,'delivery_fee'=>$vendor->delivery_fee,'total_amount'=>$total,'employer_amount'=>$employer,'employee_amount'=>$employee,'currency'=>$vendor->currency,'order_checksum'=>hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)),'prepared_by'=>$actor,'created_at'=>now(),'updated_at'=>now()]);foreach($lines as$line)DB::table('hr_meal_vendor_order_lines')->insert($line+['vendor_order_id'=>$id]);DB::table('hr_meal_employee_orders')->whereIn('id',$orders->pluck('id'))->update(['status'=>'consolidated','updated_at'=>now()]);$this->event('vendor_order',$id,'consolidated',null,'draft',['employee_order_count'=>$orders->count(),'checksum'=>hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR))],$actor);return DB::table('hr_meal_vendor_orders')->find($id);});}
 public function event(string$type,string$id,string$event,?string$from,?string$to,array$e,string$actor):void{DB::table('hr_meal_events')->insert(['id'=>(string)Str::uuid(),'aggregate_type'=>$type,'aggregate_id'=>$id,'event_type'=>$event,'from_status'=>$from,'to_status'=>$to,'evidence'=>json_encode($e,JSON_THROW_ON_ERROR),'actor_user_id'=>$actor,'occurred_at'=>now()]);}
}
